package be.winnetrie.mod.simpleserverutilities.client.gui;
import java.util.ArrayList;import java.util.List;import com.google.gson.Gson;import com.google.gson.GsonBuilder;import com.google.gson.reflect.TypeToken;import be.winnetrie.mod.simpleserverutilities.network.OnboardingAdminDataPayload;import be.winnetrie.mod.simpleserverutilities.network.OnboardingAdminRequestPayload;import be.winnetrie.mod.simpleserverutilities.network.OnboardingAdminSavePayload;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.components.EditBox;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import net.neoforged.neoforge.client.network.ClientPacketDistributor;
/** Compact three-tab administration for spawn fallbacks, rules and introduction. */
public final class OnboardingAdminScreen extends Screen{private static final Gson GSON=new GsonBuilder().create();private static final int W=650,H=380,PANEL=0xF0161D25,BORDER=0xFF586978,TEXT=0xFFF3F5F7,MUTED=0xFFAAB5BE;private OnboardingAdminDataPayload d;private final Screen parent;private Tab tab=Tab.GENERAL;private boolean enabled,requireRules,skippable,fireworks;private String title,subtitle,rules;private List<String> pages;private int page;private EditBox titleBox,subtitleBox,targetBox;private long request=1;
 public OnboardingAdminScreen(OnboardingAdminDataPayload d,Screen parent){super(Component.literal("Onboarding & Spawns"));this.d=d;this.parent=parent;load(d);}private void load(OnboardingAdminDataPayload x){d=x;enabled=x.enabled();requireRules=x.requireRules();skippable=x.skippable();fireworks=x.fireworks();title=x.welcomeTitle();subtitle=x.welcomeSubtitle();rules=x.rules();try{pages=GSON.fromJson(x.pagesJson(),new TypeToken<List<String>>(){}.getType());}catch(Exception e){pages=new ArrayList<>();}if(pages==null)pages=new ArrayList<>();page=Math.max(0,Math.min(page,Math.max(0,pages.size()-1)));}
 public void accept(OnboardingAdminDataPayload x){load(x);rebuildWidgets();}
 @Override protected void init(){int x=left(),y=top();for(Tab t:Tab.values()){Button b=addRenderableWidget(Button.builder(Component.literal(t.label),z->{collect();tab=t;rebuildWidgets();}).bounds(x+16+t.ordinal()*126,y+42,120,20).build());b.active=t!=tab;}addRenderableWidget(Button.builder(Component.literal("Close"),b->onClose()).bounds(x+W-88,y+H-28,72,20).build());addRenderableWidget(Button.builder(Component.literal("Save"),b->save()).bounds(x+W-168,y+H-28,72,20).build());switch(tab){case GENERAL->general(x,y);case RULES->rules(x,y);case INTRO->intro(x,y);}}
 private void general(int x,int y){addRenderableWidget(Button.builder(Component.literal("Enabled: "+on(enabled)),b->{enabled=!enabled;rebuildWidgets();}).bounds(x+18,y+78,150,20).build());addRenderableWidget(Button.builder(Component.literal("Require rules: "+on(requireRules)),b->{requireRules=!requireRules;rebuildWidgets();}).bounds(x+176,y+78,150,20).build());addRenderableWidget(Button.builder(Component.literal("Intro skippable: "+on(skippable)),b->{skippable=!skippable;rebuildWidgets();}).bounds(x+334,y+78,150,20).build());addRenderableWidget(Button.builder(Component.literal("Fireworks: "+on(fireworks)),b->{fireworks=!fireworks;rebuildWidgets();}).bounds(x+492,y+78,140,20).build());titleBox=box(x+18,y+126,296,title,96,"Welcome title");subtitleBox=box(x+326,y+126,306,subtitle,192,"Welcome subtitle");addRenderableWidget(Button.builder(Component.literal("Set server spawn here"),b->action("set_server_spawn","")).bounds(x+18,y+184,184,20).build());addRenderableWidget(Button.builder(Component.literal("Clear server spawn"),b->action("clear_server_spawn","")).bounds(x+210,y+184,150,20).build());addRenderableWidget(Button.builder(Component.literal("Set lobby spawn here"),b->action("set_lobby_spawn","")).bounds(x+18,y+218,184,20).build());addRenderableWidget(Button.builder(Component.literal("Clear lobby spawn"),b->action("clear_lobby_spawn","")).bounds(x+210,y+218,150,20).build());targetBox=box(x+18,y+278,250,"",64,"Player name / UUID");addRenderableWidget(Button.builder(Component.literal("Reset onboarding"),b->action("reset_player",targetBox.getValue())).bounds(x+278,y+278,140,20).build());addRenderableWidget(Button.builder(Component.literal("Mark completed"),b->action("complete_player",targetBox.getValue())).bounds(x+426,y+278,130,20).build());}
 private void rules(int x,int y){addRenderableWidget(Button.builder(Component.literal("Edit rules (rich text)"),b->minecraft.setScreenAndShow(new RichTextValueEditorScreen(this,"Server rules","Use the fixed 16 colours and text styles.",rules,v->{rules=v;}))).bounds(x+18,y+84,210,22).build());}
 private void intro(int x,int y){if(pages.isEmpty())pages.add("");addRenderableWidget(Button.builder(Component.literal("<"),b->{collect();page=Math.max(0,page-1);rebuildWidgets();}).bounds(x+18,y+84,30,20).build());addRenderableWidget(Button.builder(Component.literal(">"),b->{collect();page=Math.min(pages.size()-1,page+1);rebuildWidgets();}).bounds(x+52,y+84,30,20).build());addRenderableWidget(Button.builder(Component.literal("Edit page "+(page+1)),b->minecraft.setScreenAndShow(new RichTextValueEditorScreen(this,"Introduction page "+(page+1),"Short, clear and skippable when configured.",pages.get(page),v->pages.set(page,v)))).bounds(x+96,y+84,170,20).build());addRenderableWidget(Button.builder(Component.literal("Add page"),b->{pages.add("");page=pages.size()-1;rebuildWidgets();}).bounds(x+274,y+84,100,20).build());Button remove=addRenderableWidget(Button.builder(Component.literal("Remove page"),b->{pages.remove(page);page=Math.max(0,Math.min(page,pages.size()-1));rebuildWidgets();}).bounds(x+382,y+84,110,20).build());remove.active=pages.size()>1;}
 private EditBox box(int x,int y,int w,String value,int max,String hint){EditBox e=new EditBox(font,x,y,w,20,Component.literal(hint));e.setMaxLength(max);e.setValue(value);addRenderableWidget(e);return e;}private void collect(){if(titleBox!=null)title=titleBox.getValue();if(subtitleBox!=null)subtitle=subtitleBox.getValue();}
 private void save(){collect();send("save","");}private void action(String a,String target){collect();send(a,target);}private void send(String a,String target){ClientPacketDistributor.sendToServer(new OnboardingAdminSavePayload(a,enabled,requireRules,skippable,fireworks,title,subtitle,rules,GSON.toJson(pages),target,request++));}
 @Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float pt){int x=left(),y=top();g.fill(0,0,width,height,0xA5000000);g.fill(x,y,x+W,y+H,PANEL);g.outline(x,y,W,H,BORDER);g.text(font,"Onboarding & Spawns",x+16,y+15,TEXT,true);if(tab==Tab.GENERAL){g.text(font,"Server respawn: "+d.serverSpawnSummary(),x+18,y+166,MUTED,false);g.text(font,"Lobby spawn: "+d.lobbySpawnSummary(),x+18,y+200,MUTED,false);g.text(font,"Player onboarding state",x+18,y+258,MUTED,false);}else if(tab==Tab.RULES)g.text(font,"Rules require two confirmations before the introduction unlocks.",x+18,y+120,MUTED,false);else g.text(font,"Page "+(page+1)+" / "+Math.max(1,pages.size()),x+18,y+120,MUTED,false);if(!d.notice().isBlank())g.text(font,d.notice(),x+18,y+H-26,d.error()?0xFFFF8585:0xFF83E39A,false);super.extractRenderState(g,mx,my,pt);}@Override public void onClose(){if(minecraft!=null)minecraft.setScreenAndShow(parent);}@Override public boolean isPauseScreen(){return false;}private int left(){return(width-W)/2;}private int top(){return(height-H)/2;}private static String on(boolean b){return b?"ON":"OFF";}private enum Tab{GENERAL("General"),RULES("Rules"),INTRO("Introduction");final String label;Tab(String l){label=l;}}}
